apps.compose:
services:
  authelia:
    image: docker.io/authelia/authelia:latest
    container_name: ${CONTAINER_PREFIX}authelia
    restart: ${RESTART_POLICY}
    command: ["--config", "/config/configuration.yml"]
    environment:
      PUID: ${PUID}
      PGID: ${PGID}
      TZ: ${TZ}
      AUTHELIA_SESSION_SECRET: ${AUTHELIA_SESSION_SECRET}
      AUTHELIA_STORAGE_ENCRYPTION_KEY: ${AUTHELIA_STORAGE_KEY}
      AUTHELIA_IDENTITY_VALIDATION_RESET_PASSWORD_JWT_SECRET: ${AUTHELIA_RESET_SECRET}
    volumes:
      - ${CONFIG_PATH}/authelia/config:/config
    ports:
      - 9091:9091

services:
  bazarr:
    image: lscr.io/linuxserver/bazarr:latest
    container_name: ${CONTAINER_PREFIX}bazarr
    restart: ${RESTART_POLICY}
    environment:
      PUID: ${PUID}
      PGID: ${PGID}
      TZ: ${TZ}
      UMASK: ${UMASK}
    volumes:
      - ${CONFIG_PATH}/bazarr/config:/config
      - ${DATA_PATH}/media:/media
    ports:
      - 6767:6767

services:
  cleanuparr:
    image: ghcr.io/cleanuparr/cleanuparr:latest
    container_name: ${CONTAINER_PREFIX}cleanuparr
    restart: ${RESTART_POLICY}
    environment:
      PORT: "11011"
      PUID: ${PUID}
      PGID: ${PGID}
      TZ: ${TZ}
      UMASK: ${UMASK}
    volumes:
      - ${CONFIG_PATH}/cleanuparr/config:/config
    ports:
      - 11011:11011

services:
  cloudflare-tunnel:
    image: cloudflare/cloudflared:latest
    container_name: ${CONTAINER_PREFIX}cloudflare-tunnel
    restart: ${RESTART_POLICY}
    command: ["tunnel", "--no-autoupdate", "--metrics", "127.0.0.1:2000", "run"]
    environment:
      TZ: ${TZ}
      TUNNEL_TOKEN: ${CLOUDFLARE_TUNNEL_TOKEN}

services:
  grafana:
    image: grafana/grafana:latest
    container_name: ${CONTAINER_PREFIX}grafana
    restart: ${RESTART_POLICY}
    user: ${PUID}:${PGID}
    environment:
      GF_SECURITY_ADMIN_USER: ${ADMIN_USER}
      GF_SECURITY_ADMIN_PASSWORD: ${ADMIN_PASSWORD}
    volumes:
      - ${CONFIG_PATH}/grafana/data:/var/lib/grafana
    ports:
      - 3000:3000

services:
  lldap:
    image: lldap/lldap:latest
    container_name: ${CONTAINER_PREFIX}lldap
    restart: ${RESTART_POLICY}
    environment:
      UID: ${PUID}
      GID: ${PGID}
      LLDAP_LDAP_USER_DN: ${ADMIN_USER}
      LLDAP_LDAP_BASE_DN: dc=example,dc=com
      LLDAP_LDAP_USER_PASS: ${ADMIN_PASSWORD}
      LLDAP_JWT_SECRET: ${LLDAP_JWT_SECRET}
      LLDAP_KEY_SEED: ${LLDAP_KEY_SEED}
    volumes:
      - ${CONFIG_PATH}/lldap/data:/data
    ports:
      - 17170:17170

services:
  nzbget:
    image: ghcr.io/nzbgetcom/nzbget:latest
    container_name: ${CONTAINER_PREFIX}nzbget
    restart: ${RESTART_POLICY}
    environment:
      NZBGET_USER: ${ADMIN_USER}
      NZBGET_PASS: ${ADMIN_PASSWORD}
      PUID: ${PUID}
      PGID: ${PGID}
      TZ: ${TZ}
    volumes:
      - ${CONFIG_PATH}/nzbget/config:/config
      - ${DATA_PATH}/downloads:/downloads
    ports:
      - 6789:6789

services:
  slskd:
    image: ghcr.io/slskd/slskd:latest
    container_name: ${CONTAINER_PREFIX}slskd
    restart: ${RESTART_POLICY}
    user: ${PUID}:${PGID}
    environment:
      SLSKD_USERNAME: ${ADMIN_USER}
      SLSKD_PASSWORD: ${ADMIN_PASSWORD}
      SLSKD_API_KEY: role=ReadOnly;${SLSKD_API_KEY}
      SLSKD_DOWNLOADS_DIR: /downloads
      SLSKD_SLSK_USERNAME: ${SLSKD_SOULSEEK_USERNAME}
      SLSKD_SLSK_PASSWORD: ${SLSKD_SOULSEEK_PASSWORD}
    volumes:
      - ${CONFIG_PATH}/slskd/app:/app
      - ${DATA_PATH}/downloads:/downloads
    ports:
      - 5030:5030

services:
  stalwart-mail:
    image: stalwartlabs/stalwart:latest
    container_name: ${CONTAINER_PREFIX}stalwart-mail
    restart: ${RESTART_POLICY}
    user: ${PUID}:${PGID}
    environment:
      TZ: ${TZ}
      STALWART_HOSTNAME: ${STALWART_HOSTNAME}
      STALWART_RECOVERY_ADMIN: ${STALWART_MAIL_RECOVERY_ADMIN:-}
    volumes:
      - ${CONFIG_PATH}/stalwart-mail/configuration:/etc/stalwart
      - ${CONFIG_PATH}/stalwart-mail/data:/var/lib/stalwart
    ports:
      - 8080:8080

services:
  transmission:
    image: linuxserver/transmission:latest
    container_name: ${CONTAINER_PREFIX}transmission
    restart: ${RESTART_POLICY}
    environment:
      PUID: ${PUID}
      PGID: ${PGID}
      TZ: ${TZ}
      USER: ${ADMIN_USER}
      PASS: ${ADMIN_PASSWORD}
    volumes:
      - ${CONFIG_PATH}/transmission/config:/config
      - ${DATA_PATH}/downloads:/downloads
    ports:
      - 9091:9091
